  function gameLabel(id){const teams={WO:'키움',HT:'KIA',SS:'삼성',HH:'한화',OB:'두산',LT:'롯데',SK:'SSG',LG:'LG',NC:'NC',KT:'KT'},match=`${teams[id.slice(8,10)]||id.slice(8,10)} vs ${teams[id.slice(10,12)]||id.slice(10,12)}`;return `${id.slice(0,4)}-${id.slice(4,6)}-${id.slice(6,8)} · ${app.lang==='en'?translateTeam(match):match}`}
